	@ParameterizedTest(name = "merged prefix representatives with adjacency={0}")
	@ValueSource(booleans = { false, true })
	void mergedRunsKeepCompleteRepresentativesAndDistinctCountsAcrossContexts(boolean adjacency) throws Exception {
		LmdbStore actualStore = new LmdbStore(directory.resolve("actual").toFile(), new LmdbStoreConfig()
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(adjacency));
		LmdbStore referenceStore = new LmdbStore(directory.resolve("reference").toFile(), new LmdbStoreConfig()
				.setNativeEvaluationEnabled(false)
				.setDirectAdjacencyEnabled(false));
		SailRepository actual = new SailRepository(actualStore);
		SailRepository reference = new SailRepository(referenceStore);
		actual.init();
		reference.init();
		try {
			loadSharedPrefixes(actual, actualStore);
			loadSharedPrefixes(reference, referenceStore);
			if (adjacency) {
				assertThat(actualStore.awaitDirectAdjacencyReady(60, TimeUnit.SECONDS))
						.as(actualStore.getDirectAdjacencyReadinessDescription())
						.isTrue();
			}
			List<String> patterns = List.of("?s a ?type", "GRAPH ?g { ?s a ?type }",
					"GRAPH <urn:g1> { ?s a ?type }", "GRAPH <_:graph> { ?s a ?type }",
					"?s a ?type FILTER(?type != <urn:missing>)");
			try (var connection = actual.getConnection(); var generic = reference.getConnection()) {
				for (boolean inferred : new boolean[] { true, false }) {
					for (String pattern : patterns) {
						for (String group : List.of("?type", "?s")) {
							String text = "SELECT " + group
									+ " (COUNT(*) AS ?rows) (COUNT(DISTINCT ?s) AS ?subjects) WHERE { "
									+ pattern + " } GROUP BY " + group;
							var query = connection.prepareTupleQuery(text);
							var oracle = generic.prepareTupleQuery(text);
							((SailQuery) query).setLmdbResultCacheRequested(false);
							query.setIncludeInferred(inferred);
							oracle.setIncludeInferred(inferred);
							Map<BindingSet, Integer> expected = new HashMap<>();
							Map<BindingSet, Integer> result = new HashMap<>();
							try (var rows = oracle.evaluate()) {
								rows.forEach(row -> expected.merge(row, 1, Integer::sum));
							}
							try (var rows = query.evaluate()) {
								rows.forEach(row -> result.merge(row, 1, Integer::sum));
							}
							assertThat(result).as("includeInferred=%s; %s", inferred, text)
									.containsExactlyInAnyOrderEntriesOf(expected);
						}
					}
				}
			}
		} finally {
			actual.shutDown();
			reference.shutDown();
		}
	}

	private static void loadSharedPrefixes(SailRepository repository, LmdbStore store) {
		var vf = repository.getValueFactory();
		Resource firstGraph = vf.createIRI("urn:g1");
		Resource secondGraph = vf.createIRI("urn:g2");
		Resource blankGraph = vf.createBNode("graph");
		Value firstType = vf.createIRI("urn:Type");
		Value secondType = vf.createIRI("urn:OtherType");
		Value blankType = vf.createBNode("type");
		try (var connection = repository.getConnection()) {
			connection.add(vf.createIRI("urn:s0"), RDF.TYPE, firstType, firstGraph, secondGraph);
			connection.add(vf.createIRI("urn:s1"), RDF.TYPE, firstType, firstGraph);
			connection.add(vf.createIRI("urn:s2"), RDF.TYPE, secondType);
			connection.add(vf.createBNode("explicit"), RDF.TYPE, blankType, blankGraph);
		}
		try (InferencerConnection connection = (InferencerConnection) store.getConnection()) {
			connection.begin();
			connection.addInferredStatement(vf.createIRI("urn:s0"), RDF.TYPE, firstType);
			connection.addInferredStatement(vf.createIRI("urn:s3"), RDF.TYPE, firstType, firstGraph);
			connection.addInferredStatement(vf.createIRI("urn:s4"), RDF.TYPE, secondType, secondGraph);
			connection.addInferredStatement(vf.createIRI("urn:s5"), RDF.TYPE, vf.createIRI("urn:InferredType"));
			connection.addInferredStatement(vf.createBNode("inferred"), RDF.TYPE, blankType, blankGraph);
			connection.commit();
		}
	}
